ALTER TABLE public.transactions DISABLE TRIGGER transactions_books;
INSERT INTO public.accounts(client_id,number,name,account_type) SELECT t.client_id,'L'||row_number() OVER(PARTITION BY t.client_id ORDER BY t.account,t.direction,t.kind),COALESCE(NULLIF(t.account,''),'Legacy uncategorized')||CASE WHEN t.direction='in' THEN ' (income)' ELSE ' (expense)' END,CASE WHEN t.direction='in' THEN 'income' ELSE 'expense' END FROM public.transactions t WHERE t.status='posted' GROUP BY t.client_id,t.account,t.direction,t.kind ON CONFLICT DO NOTHING;
UPDATE public.transactions t SET category_account_id=a.id,bank_account_id=(SELECT id FROM public.accounts b WHERE b.client_id=t.client_id AND b.number=CASE WHEN t.kind='invoice' THEN '1100' WHEN t.kind='bill' THEN '2000' ELSE '1000' END) FROM public.accounts a WHERE a.client_id=t.client_id AND a.name=COALESCE(NULLIF(t.account,''),'Legacy uncategorized')||CASE WHEN t.direction='in' THEN ' (income)' ELSE ' (expense)' END AND t.status='posted' AND t.entry_id IS NULL;
INSERT INTO public.journal_entries(id,client_id,entry_number,entry_date,memo,source,created_by,created_at) SELECT t.id,t.client_id,row_number() OVER(PARTITION BY t.client_id ORDER BY t.txn_date,t.id),t.txn_date,t.description,'legacy migration',t.created_by,t.created_at FROM public.transactions t WHERE t.status='posted' AND t.entry_id IS NULL AND t.amount_cents>0;
INSERT INTO public.journal_lines(entry_id,client_id,account_id,debit_cents,credit_cents) SELECT t.id,t.client_id,CASE WHEN t.direction='in' THEN t.bank_account_id ELSE t.category_account_id END,t.amount_cents,0 FROM public.transactions t JOIN public.journal_entries j ON j.id=t.id WHERE t.entry_id IS NULL UNION ALL SELECT t.id,t.client_id,CASE WHEN t.direction='in' THEN t.category_account_id ELSE t.bank_account_id END,0,t.amount_cents FROM public.transactions t JOIN public.journal_entries j ON j.id=t.id WHERE t.entry_id IS NULL;
UPDATE public.transactions t SET entry_id=t.id WHERE EXISTS(SELECT 1 FROM public.journal_entries j WHERE j.id=t.id);
ALTER TABLE public.transactions ENABLE TRIGGER transactions_books;
CREATE FUNCTION public.add_login_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.client_id IS NOT NULL THEN INSERT INTO public.client_access(client_id,user_id,status,approved_at) VALUES(NEW.client_id,NEW.id,'approved',now()) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_access AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.add_login_access();
CREATE POLICY engagements_tenant ON public.engagements AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id));
CREATE POLICY stages_tenant ON public.engagement_stages AS RESTRICTIVE TO authenticated USING(EXISTS(SELECT 1 FROM public.engagements e WHERE e.id=engagement_id AND(public.has_company_access(e.client_id) OR public.is_company_client(e.client_id)))) WITH CHECK(EXISTS(SELECT 1 FROM public.engagements e WHERE e.id=engagement_id AND public.has_company_access(e.client_id)));
CREATE POLICY requests_tenant ON public.document_requests AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id));
CREATE POLICY messages_tenant ON public.messages AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE POLICY threads_tenant ON public.message_threads AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id));
CREATE POLICY activity_tenant ON public.activity AS RESTRICTIVE TO authenticated USING(client_id IS NULL OR public.has_company_access(client_id)) WITH CHECK(client_id IS NULL OR public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE FUNCTION public.client_txn_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.client_id<>OLD.client_id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.source<>OLD.source) THEN RAISE EXCEPTION 'Transaction ownership cannot be changed'; END IF; IF NOT public.has_company_access(NEW.client_id) AND (NEW.status<>'draft' OR NEW.source<>'client' OR NEW.created_by<>auth.uid() OR NEW.entry_id IS NOT NULL OR NEW.category_account_id IS NOT NULL OR NEW.bank_account_id IS NOT NULL) THEN RAISE EXCEPTION 'Client entries must wait for staff review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER transactions_client_guard BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.client_txn_guard();